pipeline = Pipeline(name="nightly_retrain", schedule="0 2 * * *")

@pipeline.step(retries=3)
def fetch_and_validate_data():
    df = fetch_latest_data()
    return validate_dataset(df)  # from the data-validation lesson

@pipeline.step(depends_on=fetch_and_validate_data)
def compute_features(df):
    return feature_store.compute_all(df)

@pipeline.step(depends_on=compute_features)
def train_and_evaluate(features):
    model = train(features)
    metrics = evaluate(model)
    if metrics["precision"] < MINIMUM_THRESHOLD:
        raise PipelineHalt("model failed evaluation gate, not registering")
    return model, metrics

# The orchestrator, not a person, decides what runs next, retries
# transient failures, and records exactly what happened at each step.
