import random

def grid_search(param_grid, train_and_eval, tracker):
    for combo in itertools.product(*param_grid.values()):
        config = dict(zip(param_grid.keys(), combo))
        metrics = train_and_eval(config, data_split="validation")
        tracker.log_run(config=config, metrics=metrics)  # every trial tracked

def random_search(param_distributions, n_trials, train_and_eval, tracker):
    for _ in range(n_trials):
        config = {k: random.choice(v) for k, v in param_distributions.items()}
        metrics = train_and_eval(config, data_split="validation")  # NOT the test set
        tracker.log_run(config=config, metrics=metrics)

# Whichever strategy picks the next config, every trial still goes
# through the same experiment-tracking discipline from the previous lesson.
